    leaving the output file with a zeroed token count in the header and
    truncated data. 80 / 82: else => try allocator.dupe(u8 line) — try inside
    the catch switch re-propagates OutOfMemory which is redundant with the
    previous branch. Also creates an unnecessary heap copy while line is still
    alive. 83-85: std.ArrayList(u32).init(allocator) — in current Zig ArrayList
    is unmanaged and init(allocator) no longer exists. Also tokens is
    reallocated from scratch on every loop iteration instead of being reused
    with clearRetainingCapacity. 86: try tokenizer.encode(text &tokens) —
    tokenizer encode signature is unverified (expects managed vs unmanaged
    list). 87 / 88: const window_length = std.math.add(usize max_seq 1) catch
    return CliError.InputTooLarge is computed inside the loop on every iteration
    although max_seq is loop-invariant; overflow check is an unreachable dead
    error path. 88-93: The window loop writes exactly max_seq + 1 tokens per
    line and discards all tokens beyond index max_seq without warning or
    sliding-window logic. 90: const token = if (index < tokens.items.len)
    tokens.items[index] else 3; — the padding token ID 3 is a hard-coded magic
    number unrelated to the vocabulary. If the vocab's PAD id differs or
    tokenizer.next_token_id <= 3 every padded sample is corrupted or fails with
    TokenOutOfRange. 91: try writeToken(writer token tokenizer.next_token_id) —
    a single out-of-range token aborts mid-file leaving a corrupt output file
    with a zero count header. 92: total = std.math.add(u64 total 1) catch return
    CliError.InputTooLarge; — overflow of u64 counter is unreachable (dead error
    path). Furthermore total counts tokens but it is written into count_position
    which semantically represents sample count. 94: samples_written =
    std.math.add(usize samples_written 1) ... — unreachable overflow path. 96:
    if (sample_count) |limit| if (samples_written != limit) return
    CliError.InvalidInput; — returns an error after the entire file was written
    but before the header count fix-up guaranteeing a corrupt output file
    whenever the input has fewer lines than requested. 97-100: The header fix-up
    uses out_file.writer() (a new writer instance) while the earlier writer may
    hold buffered/unflushed state without any flush() called; seek-back writes
    land in the wrong place or overwrite data. 99-100: tokenizer.next_token_id
    is written to the vocabulary field a second time with the identical value
    already written at line 65 (dead code / redundant write).
  - Whole file: No usage/help message is printed for CliError.InvalidArguments;
    program exits with an opaque error trace.
  - Whole file: Because total = samples_written (max_seq + 1) and the reserved
    fields remain zero the dataset header cannot express the number of samples.
  - Whole file: No std.fs.File.sync/flush before close and no cleanup/removal of
    partially written output on error paths.
  - Whole file: Mixed Zig standard-library API generations
    (std.io.bufferedReader GeneralPurposeAllocator ArrayList(T).init
    File.writer() value semantics std.json union comparison) — the code cannot
    compile against any single Zig version.

const std = @import("std"); const MGT = @import("tokenizer/mgt.zig").MGT; const
dataset = @import("distributed/mmap_token_dataset.zig");

const CliError = error{ InvalidArguments, InvalidInput, TokenOutOfRange,
InputTooLarge, };

fn openRead(path: []const u8) !std.fs.File { if (std.fs.path.isAbsolute(path))
return std.fs.openFileAbsolute(path, .{ .mode = .read_only }); return
std.fs.cwd().openFile(path, .{ .mode = .read_only }); }

fn openWrite(path: []const u8) !std.fs.File { if (std.fs.path.isAbsolute(path))
return std.fs.createFileAbsolute(path, .{ .truncate = true, .read = false });
return std.fs.cwd().createFile(path, .{ .truncate = true, .read = false }); }

fn extractText(allocator: std.mem.Allocator, line: []const u8) ![]const u8 {
const parsed = try std.json.parseFromSlice(std.json.Value, allocator, line, .{
.allocate = .alloc_always }); defer parsed.deinit(); if (parsed.value !=
.object) return CliError.InvalidInput; const value =
parsed.value.object.get("text") orelse return CliError.InvalidInput; if (value
!= .string or value.string.len == 0) return CliError.InvalidInput; return try
allocator.dupe(u8, value.string); }

fn writeToken(writer: anytype, value: u32, vocab_size: u32) !void { if (value >=
vocab_size) return CliError.TokenOutOfRange; try writer.writeInt(u32, value,
.little); }

pub fn main() !void { var gpa = std.heap.GeneralPurposeAllocator(.{}){}; defer _
= gpa.deinit(); const allocator = gpa.allocator();

var args = try std.process.argsWithAllocator(allocator);
defer args.deinit();

_ = args.next();
const input = args.next() orelse return CliError.InvalidArguments;
const output = args.next() orelse return CliError.InvalidArguments;
const vocab_path = args.next() orelse return CliError.InvalidArguments;
const max_seq_raw = args.next() orelse return CliError.InvalidArguments;
const max_seq = try std.fmt.parseInt(usize, max_seq_raw, 10);
if (max_seq == 0) return CliError.InvalidArguments;
const sample_count = if (args.next()) |raw| blk: {
    const value = try std.fmt.parseInt(usize, raw, 10);
    if (value == 0) return CliError.InvalidArguments;
    break :blk value;
} else null;

var tokenizer = try MGT.init(allocator, &.{}, &.{}, null, .english);
defer tokenizer.deinit();
try tokenizer.loadVocab(vocab_path);

const pad_token_id: u32 = 3;
if (tokenizer.next_token_id <= pad_token_id) return CliError.TokenOutOfRange;

const in_file = try openRead(input);
defer in_file.close();
var out_file = try openWrite(output);
defer out_file.close();

var out_buf = std.io.bufferedWriter(out_file.writer());
var writer = out_buf.writer();

try writer.writeAll(dataset.magic);
try writer.writeInt(u32, dataset.version, .little);
try writer.writeInt(u32, dataset.token_type_u32, .little);
try writer.writeInt(u64, dataset.header_size, .little);
const count_position: u64 = @intCast(out_buf.buffered_len);
try writer.writeInt(u64, 0, .little);
const vocabulary_position: u64 = @intCast(out_buf.buffered_len);
try writer.writeInt(u64, tokenizer.next_token_id, .little);
try writer.writeInt(u64, @intCast(max_seq), .little);
try writer.writeInt(u64, 0, .little);
try writer.writeInt(u64, 0, .little);

var total: u64 = 0;
var samples_written: usize = 0;
var buffered = std.io.bufferedReader(in_file.reader());
while (try buffered.reader().readUntilDelimiterOrEofAlloc(allocator, '\n', 64 * 1024 * 1024)) |raw_line| {
    defer allocator.free(raw_line);
    const line = std.mem.trimRight(u8, raw_line, "\r");
    if (sample_count) |limit| if (samples_written >= limit) {
        break;
    };
    const text = extractText(allocator, line) catch |err| switch (err) {
        error.OutOfMemory => return err,
        else => try allocator.dupe(u8, line),
    };
    defer allocator.free(text);
    var tokens = std.ArrayList(u32).init(allocator);
    defer tokens.deinit();
    try tokenizer.encode(text, &tokens);
    const window_length = std.math.add(usize, max_seq, 1) catch return CliError.InputTooLarge;
    var index: usize = 0;
    while (index < window_length) : (index += 1) {
        const token = if (index < tokens.items.len) tokens.items[index] else pad_token_id;
        try writeToken(writer, token, tokenizer.next_token_id);
        total = std.math.add(u64, total, 1) catch return CliError.InputTooLarge;
    }
    samples_written = std.math.add(usize, samples_written, 1) catch return CliError.InputTooLarge;
}
if (sample_count) |limit| if (samples_written != limit) return CliError.InvalidInput;

try out_buf.flush();
try out_file.seekTo(count_position);
try out_file.writer().writeInt(u64, total, .little);
try out_file.seekTo(vocabulary_position);
try out_file.writer().writeInt(u64, tokenizer.next_token_id, .little);

}
